        className: "language-java",
        children: "package com.company.payment.application.idempotency;\n\nimport com.company.payment.infrastructure.persistence.idempotency.IdempotencyInsertCommand;\nimport com.company.payment.infrastructure.persistence.idempotency.IdempotencyMapper;\nimport com.company.payment.infrastructure.persistence.idempotency.IdempotencyRecord;\n\nimport java.time.Clock;\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.UUID;\n\npublic class IdempotencyService {\n\n    private final IdempotencyMapper mapper;\n    private final Clock clock;\n    private final Duration processingLockTtl;\n    private final Duration keyRetentionTtl;\n\n    public IdempotencyService(\n            IdempotencyMapper mapper,\n            Clock clock,\n            Duration processingLockTtl,\n            Duration keyRetentionTtl\n    ) {\n        this.mapper = mapper;\n        this.clock = clock;\n        this.processingLockTtl = processingLockTtl;\n        this.keyRetentionTtl = keyRetentionTtl;\n    }\n\n    public IdempotencyDecision begin(\n            String operationType,\n            String operationKey,\n            String idempotencyKey,\n            String method,\n            String path,\n            String requestHash\n    ) {\n        validateKey(idempotencyKey);\n\n        Instant now = Instant.now(clock);\n\n        IdempotencyInsertCommand insert = new IdempotencyInsertCommand(\n                UUID.randomUUID(),\n                operationType,\n                operationKey,\n                idempotencyKey,\n                method,\n                path,\n                requestHash,\n                now.plus(processingLockTtl),\n                now.plus(keyRetentionTtl)\n        );\n\n        int inserted = mapper.insertProcessing(insert);\n\n        if (inserted == 1) {\n            return new IdempotencyDecision.Execute();\n        }\n\n        IdempotencyRecord existing = mapper\n                .findByOperationAndKey(operationType, idempotencyKey)\n     