itch (status) {\n            case \"requires_action\" -> GatewayPaymentStatus.REQUIRES_ACTION;\n            case \"requires_capture\" -> GatewayPaymentStatus.AUTHORIZED;\n            case \"succeeded\" -> GatewayPaymentStatus.CAPTURED;\n            case \"canceled\" -> GatewayPaymentStatus.CANCELLED;\n            case \"processing\", \"requires_confirmation\" -> GatewayPaymentStatus.AUTHORIZATION_PENDING;\n            case \"requires_payment_method\" -> GatewayPaymentStatus.FAILED;\n            default -> GatewayPaymentStatus.UNKNOWN;\n        };\n    }\n\n    private GatewayRefundStatus mapRefundStatus(String status) {\n        return switch (status) {\n            case \"succeeded\" -> GatewayRefundStatus.SUCCEEDED;\n            case \"failed\" -> GatewayRefundStatus.FAILED;\n            case \"canceled\" -> GatewayRefundStatus.CANCELLED;\n            case \"pending\" -> GatewayRefundStatus.PENDING;\n            default -> GatewayRefundStatus.UNKNOWN;\n        };\n    }\n\n    private GatewayNextAction mapNextAction(JsonNode nextAction) {\n        if (nextAction == null || nextAction.isMissingNode() || nextAction.isNull()) {\n            return null;\n        }\n\n        return new GatewayNextAction(\n                nextAction.path(\"type\").asText(null),\n                nextAction.path(\"redirect_to_url\").path(\"url\").asText(null),\n                null,\n                null,\n                null,\n                Map.of()\n        );\n    }\n\n    private JsonNode read(String body) {\n        try {\n            return objectMapper.readTree(body);\n        } catch (Exception e) {\n            throw new IllegalStateException(\"Failed to parse Stripe response\", e);\n        }\n    }\n}\n"
