irmationEvent(payment.paymentId());\n\n            return paymentResponseMapper.pendingConfirmation(payment.paymentId(), command.correlationId());\n        });\n\n    } catch (GatewayDeclinedException e) {\n        return transactionTemplate.execute(() -> {\n            paymentRepository.markFailed(payment.paymentId(), e.providerErrorCode(), e.getMessage());\n            paymentEventRepository.insertGatewayDeclinedEvent(payment.paymentId(), e);\n            outboxRepository.insertPaymentFailedEvent(payment.paymentId());\n\n            return paymentResponseMapper.failed(payment.paymentId(), command.correlationId());\n        });\n    }\n}\n"
