        className: "language-java",
        children: "package com.company.payment.routing;\n\nimport java.time.Instant;\nimport java.util.Comparator;\nimport java.util.List;\nimport java.util.UUID;\n\npublic class DefaultPaymentRoutingService implements PaymentRoutingService {\n\n    private final MerchantPaymentConfigRepository merchantConfigRepository;\n    private final ProviderCapabilityRepository capabilityRepository;\n    private final ProviderHealthRepository healthRepository;\n    private final PaymentRoutingRuleRepository ruleRepository;\n    private final PaymentRoutingDecisionRepository decisionRepository;\n\n    public DefaultPaymentRoutingService(\n            MerchantPaymentConfigRepository merchantConfigRepository,\n            ProviderCapabilityRepository capabilityRepository,\n            ProviderHealthRepository healthRepository,\n            PaymentRoutingRuleRepository ruleRepository,\n            PaymentRoutingDecisionRepository decisionRepository\n    ) {\n        this.merchantConfigRepository = merchantConfigRepository;\n        this.capabilityRepository = capabilityRepository;\n        this.healthRepository = healthRepository;\n        this.ruleRepository = ruleRepository;\n        this.decisionRepository = decisionRepository;\n    }\n\n    @Override\n    public PaymentRoutingDecision selectProviderForCreatePayment(\n            UUID paymentId,\n            PaymentRoutingContext context\n    ) {\n        List<MerchantProviderConfig> merchantProviders =\n                merchantConfigRepository.findEnabledByMerchantId(context.merchantId());\n\n        if (merchantProviders.isEmpty()) {\n            throw new PaymentRoutingException(\n                    \"NO_MERCHANT_PROVIDER_CONFIG\",\n                    \"No enabled payment provider configured for merchant\"\n            );\n        }\n\n        List<ProviderCandidate> candidates = merchantProviders.stream()\n                .map(config -> buildCandidate(config, context))\n                .filter(candidate -> candidate.isProviderEnabled())\n                .filter(candidate -> candidate.supportsCurrency(context.currency()))\n                .filter(candidate -> candidate.supportsPaymentMethod(context.paymentMethodType()))\n                .filter(candidate -> candidate.supportsCountry(context.customerCountry()))\n                .filter(candidate -> candidate.supportsCaptureMode(context.captureImmediately()))\n                .filter(candidate -> candidate.isAmountWithinLimit(context.amountMinor()))\n                .filter(candidate -> candidate.canAcceptNewPayment())\n                .toList();\n\n        if (candidates.isEmpty()) {\n            throw new PaymentRoutingException(\n                    \"NO_ELIGIBLE_PROVIDER\",\n                    \"No eligible payment provider found for this payment context\"\n            );\n        }\n\n        List<PaymentRoutingRule> matchingRules =\n                ruleRepository.findMatchingRules(context);\n\n        ProviderCandidate selected = selectByRuleAndPriority(candidates, matchingRules, context);\n\n        PaymentRoutingDecision decision = new PaymentRoutingDecision(\n                UUID.randomUUID(),\n                paymentId,\n                selected.providerCode(),\n                selected.providerAccountId(),\n                selected.matchedRuleId(),\n                selected.matchedRuleVersion(),\n                selected.decisionReason(),\n                candidates.stream().map(ProviderCandidate::providerCode).toList(),\n                List.of(),\n                false,\n                null,\n                selected.decisionAttributes(),\n                Instant.now()\n        );\n\n        decisionRepository.insert(decision);\n\n        return decision;\n    }\n\n    @Override\n    public String providerForExistingPayment(UUID paymentId) {\n        return decisionRepository.findByPaymentId(paymentId)\n                .map(PaymentRoutingDecision::selectedProvider)\n                .orElseThrow(() -> new PaymentRoutingException(\n                        \"ROUTING_DECISION_NOT_FOUND\",\n                        \"Routing decision not found for payment\"\n                ));\n    }\n\n    @Override\n    public PaymentRoutingDecision dryRun(PaymentRoutingContext context) {\n        UUID fakePaymentId = UUID.randomUUID();\n\n        /*\n         * In real implementation, do not insert decision.\n         * Return computed decision only.\n         */\n        throw new UnsupportedOperationException(\"Implement dry-run without persistence\");\n    }\n\n    private ProviderCandidate buildCandidate(\n            MerchantProviderConfig config,\n            PaymentRoutingContext context\n    ) {\n        ProviderCapability capability =\n                capabilityRepository.findByProviderCode(config.providerCode());\n\n        ProviderHealth health =\n                healthRepository.findByProviderCode(config.providerCode());\n\n        return ProviderCandidate.from(config, capability, health, context);\n    }\n\n    private ProviderCandidate selectByRuleAndPriority(\n            List<ProviderCandidate> candidates,\n            List<PaymentRoutingRule> rules,\n            PaymentRoutingContext context\n    ) {\n        for (PaymentRoutingRule rule : rules.stream()\n                .sorted(Comparator.comparingInt(PaymentRoutingRule::priority))\n                .toList()) {\n\n            for (ProviderCandidate candidate : candidates) {\n                if (candidate.providerCode().equals(rule.providerCode())) {\n                    return candidate.withMatchedRule(rule);\n                }\n            }\n        }\n\n        return candidates.stream()\n                .sorted(\n                        Comparator\n                                .comparingInt(ProviderCandidate::merchantPriority)\n                                .thenComparing(ProviderCandidate::providerCode)\n                )\n                .findFirst()\n                .orElseThrow();\n    }\n}\n"
