ately) {\n            return capability.supportsCapture();\n        }\n        return capability.supportsAuthorize() && capability.supportsCapture();\n    }\n\n    public boolean isAmountWithinLimit(long amountMinor) {\n        if (minAmountMinor != null && amountMinor < minAmountMinor) {\n            return false;\n        }\n        if (maxAmountMinor != null && amountMinor > maxAmountMinor) {\n            return false;\n        }\n        return true;\n    }\n\n    public boolean canAcceptNewPayment() {\n        return health.canAcceptNewPayment();\n    }\n\n    public ProviderCandidate withMatchedRule(PaymentRoutingRule rule) {\n        return new ProviderCandidate(\n                providerCode,\n                providerAccountId,\n                merchantPriority,\n                capability,\n                health,\n                rule.routingRuleId().toString(),\n                rule.ruleVersion(),\n                \"Selected by routing rule: \" + rule.ruleName(),\n                minAmountMinor,\n                maxAmountMinor,\n                decisionAttributes\n        );\n    }\n}\n"
