        children: "package com.company.payment.routing;\n\nimport java.util.UUID;\n\npublic record PaymentRoutingRule(\n        UUID routingRuleId,\n        String ruleName,\n        int ruleVersion,\n\n        String merchantId,\n        String providerCode,\n        String paymentMethodType,\n        String currency,\n        String customerCountry,\n\n        Long minAmountMinor,\n        Long maxAmountMinor,\n\n        String captureMode,\n        String channel,\n\n        int priority,\n        boolean fallbackAllowed\n) {\n    public boolean matches(PaymentRoutingContext context) {\n        return matchesNullable(merchantId, context.merchantId())\n                && matchesNullable(paymentMethodType, context.paymentMethodType())\n                && matchesNullable(currency, context.currency())\n                && matchesNullable(customerCountry, context.customerCountry())\n                && matchesAmount(context.amountMinor())\n                && matchesCaptureMode(context.captureImmediately())\n                && matchesNullable(channel, context.channel());\n    }\n\n    private boolean matchesNullable(String ruleValue, String actualValue) {\n        return ruleValue == null || ruleValue.equals(actualValue);\n    }\n\n    private boolean matchesAmount(long amountMinor) {\n        if (minAmountMinor != null && amountMinor < minAmountMinor) {\n            return false;\n        }\n        if (maxAmountMinor != null && amountMinor > maxAmountMinor) {\n            return false;\n        }\n        return true;\n    }\n\n    private boolean matchesCaptureMode(boolean captureImmediately) {\n        if (captureMode == null) {\n            return true;\n        }\n\n        String actual = captureImmediately ? \"AUTO\" : \"MANUAL\";\n        return captureMode.equals(actual);\n    }\n}\n"
