        children: "package com.company.payment.application;\n\nimport com.company.payment.api.dto.CreateRefundRequest;\nimport com.company.payment.api.dto.RefundResponse;\n\nimport java.util.UUID;\n\npublic class RefundApplicationService {\n\n    private final IdempotencyService idempotencyService;\n    private final RequestHashCalculator requestHashCalculator;\n    private final PaymentRepository paymentRepository;\n    private final RefundRepository refundRepository;\n    private final PaymentGatewayRegistry gatewayRegistry;\n    private final GatewayRequestFactory gatewayRequestFactory;\n    private final RefundResultApplier refundResultApplier;\n    private final TransactionTemplate transactionTemplate;\n\n    public RefundResponse createRefund(\n            UUID paymentId,\n            String idempotencyKey,\n            String correlationId,\n            CreateRefundRequest request\n    ) {\n        String requestHash = requestHashCalculator.calculate(\n                \"POST\",\n                \"/payments/{paymentId}/refunds\",\n                request\n        );\n\n        IdempotencyDecision decision = idempotencyService.begin(\n                \"CREATE_REFUND\",\n                paymentId.toString(),\n                idempotencyKey,\n                \"POST\",\n                \"/payments/{paymentId}/refunds\",\n                requestHash\n        );\n\n        if (decision instanceof IdempotencyDecision.ReturnCached cached) {\n            return RefundResponseMapper.fromJson(cached.responseBodyJson());\n        }\n\n        if (decision instanceof IdempotencyDecision.Processing) {\n            throw PaymentErrors.operationAlreadyProcessing(correlationId);\n        }\n\n        if (decision instanceof IdempotencyDecision.Conflict conflict) {\n            throw PaymentErrors.idempotencyConflict(conflict.message(), correlationId);\n        }\n\n        RefundPreparation prepared = transactionTemplate.execute(() -> {\n            PaymentRecord payment = paymentRepository.findByIdForUpdate(paymentId);\n\n            validateRefundAllowed(payment, request);\n\n            long availableRefundableAmount =\n                    refundRepository.calculateAvailableRefundableAmount(paymentId);\n\n            if (request.amountMinor() > availableRefundableAmount) {\n                throw PaymentErrors.refundExceedsCapturedAmount(paymentId, correlationId);\n            }\n\n            UUID refundId = UUID.randomUUID();\n\n            RefundRecord refund = refundRepository.insertProviderPending(\n                    refundId,\n                    payment,\n                    request,\n                    idempotencyKey,\n                    buildProviderIdempotencyKey(payment.provider(), idempotencyKey)\n            );\n\n            refundRepository.insertRefundEvent(\n                    refundId,\n                    paymentId,\n                    \"REFUND_REQUESTED\",\n                    null,\n                    \"PROVIDER_PENDING\",\n                    correlationId\n            );\n\n            return new RefundPreparation(payment, refund);\n        });\n\n        PaymentGatewayClient gateway =\n                gatewayRegistry.getRequired(prepared.payment().provider());\n\n        GatewayRefundRequest gatewayRequest =\n                gatewayRequestFactory.createRefundRequest(prepared.payment(), prepared.refund());\n\n        try {\n            GatewayRefundResult result = gateway.refund(gatewayRequest);\n\n            RefundResponse response = refundResultApplier.applyProviderRefundResult(\n                    prepared.payment(),\n                    prepared.refund(),\n                    result,\n                    correlationId,\n                    idempotencyKey,\n                    requestHash\n            );\n\n            return response;\n\n        } catch (GatewayTimeoutException e) {\n            return transactionTemplate.execute(() -> {\n                refundRepository.markUnknown(prepared.refund().refundId(), e);\n                refundRepository.insertRefundEvent(\n                        prepared.refund().refundId(),\n                        paymentId,\n                        \"REFUND_PROVIDER_TIMEOUT\",\n                        \"PROVIDER_PENDING\",\n                        \"UNKNOWN\",\n                        correlationId\n                );\n\n                RefundResponse response =\n                        RefundResponseMapper.unknown(prepared.refund(), correlationId);\n\n                idempotencyService.markSucceeded(\n                        \"CREATE_REFUND\",\n                        idempotencyKey,\n                        requestHash,\n                        202,\n                        response\n                );\n\n                return response;\n            });\n\n        } catch (GatewayDeclinedException | GatewayInvalidRequestException e) {\n            return transactionTemplate.execute(() -> {\n                refundRepository.markFailed(prepared.refund().refundId(), e);\n                refundRepository.insertRefundEvent(\n                        prepared.refund().refundId(),\n                        paymentId,\n                        \"REFUND_FAILED\",\n                        \"PROVIDER_PENDING\",\n                        \"FAILED\",\n                        correlationId\n                );\n\n                RefundResponse response =\n                        RefundResponseMapper.failed(prepared.refund(), e, correlationId);\n\n                idempotencyService.markSucceeded(\n                        \"CREATE_REFUND\",\n                        idempotencyKey,\n                        requestHash,\n                        200,\n                        response\n                );\n\n                return response;\n            });\n        }\n    }\n\n    private void validateRefundAllowed(PaymentRecord payment, CreateRefundRequest request) {\n        if (!payment.currency().equals(request.currency())) {\n            throw 