        children: "package com.company.payment.application.dispute;\n\npublic class DisputeWebhookHandler {\n\n    private final ProviderDisputeEventMapperRegistry mapperRegistry;\n    private final DisputeRepository disputeRepository;\n    private final PaymentRepository paymentRepository;\n    private final DisputeTaskRepository taskRepository;\n    private final LedgerRepository ledgerRepository;\n    private final OutboxRepository outboxRepository;\n\n    public void handle(PaymentInboxEventRecord inboxEvent) {\n        ProviderDisputeEvent event =\n                mapperRegistry.map(inboxEvent.provider(), inboxEvent.parsedPayloadJson());\n\n        if (event.category() == ProviderDisputeEventCategory.UNKNOWN) {\n            markUnknownDisputeEvent(inboxEvent, event);\n            return;\n        }\n\n        DisputeRecord existing =\n                disputeRepository.findByProviderDisputeIdForUpdate(\n                        event.provider(),\n                        event.providerDisputeId()\n                );\n\n        if (existing == null) {\n            createDisputeFromProviderEvent(inboxEvent, event);\n            return;\n        }\n\n        applyDisputeUpdate(existing, inboxEvent, event);\n    }\n\n    private void createDisputeFromProviderEvent(\n            PaymentInboxEventRecord inboxEvent,\n            ProviderDisputeEvent event\n    ) {\n        PaymentRecord payment = paymentRepository\n                .findByProviderRefs(event.provider(), event.providerPaymentId(), event.providerChargeId())\n                .orElseThrow(() -> new RecoverableWebhookProcessingException(\n                        \"PAYMENT_REFERENCE_NOT_FOUND\",\n                        \"Payment not found for dispute event\",\n                        RetrySchedule.inMinutes(5)\n                ));\n\n        DisputeRecord dispute = disputeRepository.insertOpened(\n                payment.paymentId(),\n                event\n        );\n\n        disputeRepository.insertDisputeEvent(\n                dispute.disputeId(),\n                payment.paymentId(),\n                \"DISPUTE_OPENED\",\n                \"WEBHOOK\",\n                null,\n                dispute.status(),\n                inboxEvent.providerEventId(),\n                inboxEvent.rawPayload()\n        );\n\n        paymentRepository.markDisputed(payment.paymentId());\n\n        taskRepository.createEvidenceReviewTask(\n                dispute.disputeId(),\n                event.evidenceDueAt()\n        );\n\n        outboxRepository.insertDisputeOpened(\n                payment.paymentId(),\n                dispute.disputeId(),\n                event\n        );\n\n        /*\n         * Ledger impact depends on provider/network event:\n         * some disputes immediately debit/hold amount,\n         * others are inquiry/pre-dispute with no immediate financial impact.\n         */\n        if (shouldPostChargebackHold(event)) {\n            ledgerRepository.insertChargebackHoldIfAbsent(\n                    payment.paymentId(),\n                    dispute.disputeId(),\n                    event.providerDisputeId(),\n                    event.disputedAmountMinor(),\n                    event.currency()\n            );\n        }\n    }\n\n    private void applyDisputeUpdate(\n            DisputeRecord dispute,\n            PaymentInboxEventRecord inboxEvent,\n            ProviderDisputeEvent event\n    ) {\n        switch (event.category()) {\n            case DISPUTE_WON -> applyWon(dispute, inboxEvent, event);\n            case DISPUTE_LOST -> applyLost(dispute, inboxEvent, event);\n            case EVIDENCE_REQUIRED, DISPUTE_UPDATED -> applyUpdated(dispute, inboxEvent, event);\n            case DISPUTE_CANCELLED -> applyCancelled(dispute, inboxEvent, event);\n            default -> markUnknownDisputeEvent(inboxEvent, event);\n        }\n    }\n}\n"
