        children: "package com.company.payment.reconciliation.matching;\n\npublic class InternalRefundMatcher {\n\n    private final RefundRepository refundRepository;\n\n    public ReconciliationDecision matchRefund(\n            UUID reconciliationRunId,\n            ProviderFinancialTransaction tx\n    ) {\n        RefundRecord refund = refundRepository\n                .findByProviderRefundId(tx.provider(), tx.providerRefundId())\n                .orElse(null);\n\n        if (refund == null) {\n            return ReconciliationDecisionFactory.missingInternal(\n                    reconciliationRunId,\n                    tx,\n                    \"REFUND\",\n                    \"Provider refund not found internally\"\n            );\n        }\n\n        if (!refund.currency().equals(tx.currency())) {\n            return ReconciliationDecisionFactory.currencyMismatch(\n                    reconciliationRunId,\n                    tx,\n                    refund.paymentId(),\n                    null,\n                    refund.refundId(),\n                    null,\n                    refund.amountMinor(),\n                    tx.grossAmountMinor(),\n                    refund.currency(),\n                    tx.currency()\n            );\n        }\n\n        long providerRefundAmount = Math.abs(tx.grossAmountMinor());\n\n        if (refund.amountMinor() != providerRefundAmount) {\n            return ReconciliationDecisionFactory.amountMismatch(\n                    reconciliationRunId,\n                    tx,\n                    refund.paymentId(),\n                    null,\n                    refund.refundId(),\n                    null,\n                    refund.amountMinor(),\n                    providerRefundAmount,\n                    refund.currency()\n            );\n        }\n\n        if (!\"SUCCEEDED\".equals(refund.status())) {\n            return ReconciliationDecisionFactory.statusMismatch(\n                    reconciliationRunId,\n  