        children: "public class StripeErrorMapper implements GatewayErrorMapper {\n\n    @Override\n    public GatewayException toException(GatewayHttpResponse response) {\n        int status = response.statusCode();\n\n        String providerRequestId = response.headers().get(\"Request-Id\");\n        String errorCode = extractErrorCode(response.body());\n        String message = extractMessage(response.body());\n\n        if (status == 402) {\n            return new GatewayDeclinedException(\n                    \"STRIPE\",\n                    errorCode,\n                    providerRequestId,\n                    message\n            );\n        }\n\n        if (status == 400 || status == 404) {\n            return new GatewayInvalidRequestException(\n                    \"STRIPE\",\n                    errorCode,\n                    providerRequestId,\n                    message\n            );\n        }\n\n        if (status == 401 || status == 403) {\n            return new GatewayInvalidRequestException(\n                    \"STRIPE\",\n                    \"AUTHENTICATION_OR_AUTHORIZATION_ERROR\",\n                    providerRequestId,\n                    message\n            );\n        }\n\n        if (status == 409 || status == 429 || status >= 500) {\n            return new GatewayUnavailableException(\n                    \"STRIPE\",\n                    errorCode,\n                    providerRequestId\n            );\n        }\n\n        return new GatewayUnknownResponseException(\n                \"STRIPE\",\n                errorCode,\n                providerRequestId,\n                \"Unexpected provider response: \" + status\n        );\n    }\n\n    @Override\n    public GatewayException toNetworkException(Exception exception, String provider) {\n        if (exception instanceof java.net.SocketTimeoutException) {\n            return new GatewayTimeoutException(provider, null);\n        }\n\n        return new GatewayUnavailableExceptio