        children: "package com.company.payment.gateway;\n\nimport com.company.payment.observability.PaymentMetrics;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Map;\n\npublic class InstrumentedPaymentGatewayClient implements PaymentGatewayClient {\n\n    private final PaymentGatewayClient delegate;\n    private final PaymentMetrics metrics;\n\n    public InstrumentedPaymentGatewayClient(\n            PaymentGatewayClient delegate,\n            PaymentMetrics metrics\n    ) {\n        this.delegate = delegate;\n        this.metrics = metrics;\n    }\n\n    @Override\n    public GatewayCaptureResult capture(GatewayCaptureRequest request) {\n        Instant start = Instant.now();\n\n        Map<String, String> labels = Map.of(\n                \"provider\", request.provider(),\n                \"operation\", \"CAPTURE\"\n        );\n\n        metrics.incrementCounter(\n                \"payment_provider_requests_total\",\n                with(labels, \"result\", \"started\")\n        );\n\n        try {\n            GatewayCaptureResult result = delegate.capture(request);\n\n            metrics.incrementCounter(\n                    \"payment_provider_requests_total\",\n                    with(labels, \"result\", result.status().name())\n            );\n\n            return result;\n\n        } catch (GatewayTimeoutException e) {\n            metrics.incrementCounter(\n                    \"payment_provider_timeout_total\",\n                    labels\n            );\n            throw e;\n\n        } catch (GatewayException e) {\n            metrics.incrementCounter(\n                    \"payment_provider_requests_total\",\n                    with(labels, \"result\", e.getClass().getSimpleName())\n            );\n            throw e;\n\n        } finally {\n            metrics.recordDuration(\n                    \"payment_provider_request_duration_seconds\",\n                    Duration.between(start, Instant.now()),\n                    labels\n            );\n        }\n    }\n\n    private Map<String, String> with(\n            Map<String, String> labels,\n            String key,\n            String value\n    ) {\n        java.util.HashMap<String, String> copy = new java.util.HashMap<>(labels);\n        copy.put(key, value);\n        return copy;\n    }\n}\n"
